// runTrailUpdateWithClientAtPath applies a trail update once the repo route and
// API client are resolved.
func runTrailUpdateWithClientAtPath(ctx context.Context, w io.Writer, client *api.Client, basePath string, inputs trailUpdateInputs) error {
	// Determine branch.
	branch := inputs.Branch
	if branch == "" {
		current, err := GetCurrentBranch(ctx)
		if err != nil {
			return fmt.Errorf("failed to determine current branch: %w", err)
		}
		branch = current
	}

