func TestRunTrailUpdateWithClient_EtagFetchFailureSendsNoBodyWrite(t *testing.T) {
	t.Parallel()

	var bodyPutCalls atomic.Int32
	var metadataPatchCalls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodGet && r.URL.Path == trailTestBasePath:
			w.Header().Set("Content-Type", "application/json")
			if err := json.NewEncoder(w).Encode(api.TrailListResponse{
				Trails: []api.TrailResource{{ID: "trl_1", Number: 7, Branch: "feature/x", Status: string(trail.StatusOpen)}},
				Total:  1,
			}); err != nil {
				t.Errorf("encode list response: %v", err)
			}
		case r.Method == http.MethodGet && r.URL.Path == trailTestBasePath+"/7":
			w.WriteHeader(http.StatusInternalServerError)
		case r.Method == http.MethodPatch && r.URL.Path == trailTestBasePath+"/7":
			metadataPatchCalls.Add(1)
			w.Header().Set("Content-Type", "application/json")
			if err := json.NewEncoder(w).Encode(api.TrailUpdateResponse{Trail: api.TrailResource{ID: "trl_1", Number: 7}}); err != nil {
				t.Errorf("encode update response: %v", err)
			}
		case r.Method == http.MethodPut && r.URL.Path == trailTestBasePath+"/7/body":
			bodyPutCalls.Add(1)
			w.Header().Set("Content-Type", "application/json")
			if err := json.NewEncoder(w).Encode(api.TrailBodyDocument{TextSnapshot: "new body"}); err != nil {
				t.Errorf("encode body response: %v", err)
			}
		default:
			t.Errorf("unexpected request: %s %s", r.Method, r.URL.Path)
		}
	}))
	defer srv.Close()

	err := runTrailUpdateWithClientAtPath(t.Context(), io.Discard, api.NewClientWithBaseURL("tok", srv.URL), trailTestBasePath, trailUpdateInputs{
		Branch:       "feature/x",
		Title:        "new title",
		TitleChanged: true,
		Body:         "new body",
		BodyChanged:  true,
	})

	require.Zero(t, bodyPutCalls.Load(), "a failed concurrency-verification read must stop before the body PUT")
	require.Zero(t, metadataPatchCalls.Load(), "verification must complete before any part of a combined update mutates the trail")
	require.ErrorContains(t, err, "could not verify trail body is unchanged")
}

func TestRunTrailUpdateWithClient_InteractiveBodyReadFailureSendsNoWrite(t *testing.T) {
	// Not parallel: accessible huh forms read from the process-wide os.Stdin.
	t.Setenv("ACCESSIBLE", "1")
	input, err := os.CreateTemp(t.TempDir(), "trail-update-input")
	require.NoError(t, err)
	_, err = input.WriteString("\n\nnew body\n")
	require.NoError(t, err)
	_, err = input.Seek(0, io.SeekStart)
	require.NoError(t, err)
	previousStdin := os.Stdin
	os.Stdin = input
	t.Cleanup(func() {
		os.Stdin = previousStdin
		require.NoError(t, input.Close())
	})

	var bodyPutCalls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodGet && r.URL.Path == trailTestBasePath:
			w.Header().Set("Content-Type", "application/json")
			if err := json.NewEncoder(w).Encode(api.TrailListResponse{
				Trails: []api.TrailResource{{
					ID: "trl_1", Number: 7, Branch: "feature/x", Title: "Trail", Body: "old body", Status: string(trail.StatusOpen),
				}},
				Total: 1,
			}); err != nil {
				t.Errorf("encode list response: %v", err)
			}
		case r.Method == http.MethodGet && r.URL.Path == trailTestBasePath+"/7":
			w.WriteHeader(http.StatusInternalServerError)
		case r.Method == http.MethodPut && r.URL.Path == trailTestBasePath+"/7/body":
			bodyPutCalls.Add(1)
			w.Header().Set("Content-Type", "application/json")
			if err := json.NewEncoder(w).Encode(api.TrailBodyDocument{TextSnapshot: "new body"}); err != nil {
				t.Errorf("encode body response: %v", err)
			}
		default:
			t.Errorf("unexpected request: %s %s", r.Method, r.URL.Path)
		}
	}))
	defer srv.Close()

	err = runTrailUpdateWithClientAtPath(t.Context(), io.Discard, api.NewClientWithBaseURL("tok", srv.URL), trailTestBasePath, trailUpdateInputs{
		Branch: "feature/x",
	})

	require.Zero(t, bodyPutCalls.Load(), "a failed interactive body read must stop before any replacement")
	require.ErrorContains(t, err, "could not load current trail body")
}

func TestTrailUpdateCmdHasCollaborationFlags(t *testing.T) {
	t.Parallel()
	cmd := newTrailUpdateCmd()
	for _, name := range []string{"add-assignee", "remove-assignee", "add-reviewer", "remove-reviewer", "type", "priority", "overwrite"} {
		if cmd.Flags().Lookup(name) == nil {
			t.Errorf("trail update missing --%s flag", name)
		}
	}
}

